#include <tunables/global>

/usr/sbin/myapp {
  #include <abstractions/base>
  capability net_bind_service,

  /etc/myapp/** r,
  /var/log/myapp/*.log w,
  /var/lib/myapp/ rw,
  /var/lib/myapp/** rwk,
  /usr/sbin/myapp mr,

  network inet stream,

  deny /etc/shadow r,
  deny /home/** rwx,
}

